fast.replacement:
let covered = 0, n = 0;
re.lastIndex = 0;
let m: RegExpExecArray | null;
while ((m = re.exec(text)) !== null) {
  if (m.index !== covered || m[0].length === 0) return null;
  covered += m[0].length;
  n += fastChunkCount(m[0]);
}
return covered === text.length ? n : null;

